// The language files of this program are written by tools/i18n_generate.py of URTC-COMMON from its catalog: nobody edits them by hand.
// urtc_i18n.lock.json lists every generated file with its SHA-256 (line ends do not count). A file that differs, a file that is missing and a
// language file that is not in the lock all fail here, with no need of the other repository; the comparison with what the catalog generates is
// made there (python tools/i18n_generate.py check). This file is copied by i18n_generate.py sync: change the original, not this copy.
import { describe, expect, it } from "vitest";
import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(__dirname, "..", "..");
const lock = JSON.parse(readFileSync(join(ROOT, "urtc_i18n.lock.json"), "utf8")) as {
  format: number;
  catalog: string;
  catalog_sha256: string;
  files: Record<string, string>;
};

const digest = (path: string) => createHash("sha256").update(readFileSync(path).toString("latin1").replace(/\r\n/g, "\n"), "latin1").digest("hex");

describe("the generated language files", () => {
  it("are listed by a lock that names the catalog", () => {
    expect(lock.format).toBe(1);
    expect(lock.catalog.startsWith("spec/i18n/catalog/")).toBe(true);
    expect(lock.catalog_sha256).toHaveLength(64);
    expect(Object.keys(lock.files).filter(path => path.endsWith(".json"))).toHaveLength(8);
  });

  it("are not edited by hand", () => {
    for (const [relative, expected] of Object.entries(lock.files)) {
      const found = join(ROOT, relative);
      expect(existsSync(found), `${relative} is missing: run tools/i18n_generate.py sync of URTC-COMMON`).toBe(true);
      expect(digest(found), `${relative} differs from the lock: change the catalog of URTC-COMMON and sync, do not edit the file`).toBe(expected);
    }
  });

  it("are all the language files there are", () => {
    const known = new Set(Object.keys(lock.files));
    for (const name of readdirSync(join(ROOT, "src", "locales")).filter(name => name.endsWith(".json"))) {
      expect(known.has(`src/locales/${name}`), `${name} is not generated by the catalog`).toBe(true);
    }
  });
});
